export const getRequestPayoutUrl = () => {




  return `/api/payouts`
}

/**
 * @summary Request a payout from available commissions
 */
export const requestPayout = async (payoutRequestInput: PayoutRequestInput, options?: Parameters<typeof customFetch>[1]): Promise<Payout> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<Payout>(getRequestPayoutUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(payoutRequestInput)
  }
);}





export const getRequestPayoutMutationKey = () => ['requestPayout'] as const;

export const getRequestPayoutMutationOptions = <TError = ErrorType<void>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof requestPayout>>, TError,RequestPayoutMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof requestPayout>>, TError,RequestPayoutMutationVariables, TContext> => {

const mutationKey = getRequestPayoutMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof requestPayout>>, RequestPayoutMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  requestPayout(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type RequestPayoutMutationResult = NonNullable<Awaited<ReturnType<typeof requestPayout>>>
    export type RequestPayoutMutationBody = BodyType<PayoutRequestInput>
    export type RequestPayoutMutationError = ErrorType<void>
    export type RequestPayoutMutationVariables = {data: BodyType<PayoutRequestInput>}

    /**
 * @summary Request a payout from available commissions
 */
export const useRequestPayout = <TError = ErrorType<void>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof requestPayout>>, TError,RequestPayoutMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof requestPayout>>,
        TError,
        RequestPayoutMutationVariables,
        TContext
      > => {
      return useMutation(getRequestPayoutMutationOptions(options), queryClient);
    }

